1	//! Pure logical-member audit over caller-acquired bounded bytes.
2	//! No file, publication, observation-history or durability authority is conferred.
3	//! Callers must acquire immutable bounded slices and reject noncanonical physical
4	//! CID spellings before constructing typed CIDs; this API cannot inspect spelling.
5	use crate::{
6	    evidence::{self, Decoded, Kind, Record},
7	    evidence_attestation::{self as proof, Frontier, Purpose},
8	    evidence_copy_plan::Plan,
9	    evidence_recovery_commitment::{Counts, Domain, Header, Limits, MemberFraming},
10	    evidence_recovery_observation::Context,
11	    evidence_service as service,
12	    evidence_store::Committed,
13	};
14	use atproto_dasl::{Cid, Ipld};
15	use sha2::{Digest, Sha256};
16	use std::{
17	    collections::{BTreeMap, BTreeSet},
18	    sync::{
19	        atomic::{AtomicBool, Ordering},
20	        Arc,
21	    },
22	    time::{Duration, Instant},
23	};
24	const MAX_OBJECT: usize = 4 * 1024 * 1024;
25	type Result<T> = std::result::Result<T, Error>;
26	#[derive(Debug, thiserror::Error, PartialEq, Eq)]
27	pub enum Error {
28	    #[error("invalid recovery member: {0}")]
29	    Invalid(&'static str),
30	    #[error("recovery member budget exhausted")]
31	    Budget,
32	    #[error("recovery member verification cancelled")]
33	    Cancelled,
34	}
35	fn framing_error(error: crate::evidence_recovery_commitment::Error) -> Error {
36	    use crate::evidence_recovery_commitment::Error as E;
37	    match error {
38	        E::Cancelled => Error::Cancelled,
39	        E::Budget => Error::Budget,
40	        E::Shape(_) | E::Poisoned => Error::Invalid("member framing"),
41	    }
42	}
43	fn require(ok: bool, reason: &'static str) -> Result<()> {
44	    if ok {
45	        Ok(())
46	    } else {
47	        Err(Error::Invalid(reason))
48	    }
49	}
50	#[derive(Clone)]
51	pub struct Budget {
52	    /// Sum of supplied record, membership and original-object rows.
53	    pub items: u64,
54	    /// Sum of input metadata/plan/payload bytes and canonical membership keys + lengths.
55	    /// Bounds retained metadata indirectly; this is not a measured RSS ceiling.
56	    pub input_bytes: u64,
57	    pub duration: Duration,
58	    pub cancelled: Arc<AtomicBool>,
59	}
60	#[derive(Clone, Copy)]
61	pub struct Row<'a> {
62	    pub sequence: u64,
63	    pub manifest: &'a [u8],
64	    pub receipt: &'a [u8],
65	    pub proof: &'a [u8],
66	}
67	#[derive(Clone, Copy)]
68	pub struct Object<'a> {
69	    pub cid: &'a Cid,
70	    pub bytes: &'a [u8],
71	}
72	#[derive(Clone, Copy)]
73	pub struct Membership<'a> {
74	    pub cid: &'a Cid,
75	    pub length: u64,
76	}
77	#[derive(Clone, Copy)]
78	pub struct Input<'a> {
79	    pub context: &'a Context,
80	    pub plan: Option<&'a [u8]>,
81	    pub membership: &'a [Membership<'a>],
82	    pub records: &'a [Row<'a>],
83	    pub objects: &'a [Object<'a>],
84	}
85	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
86	pub enum Availability {
87	    Available,
88	    Missing,
89	    Corrupt,
90	}
91	/// Why a loss coordinate exists. This is recomputed from the immutable member,
92	/// never supplied by the observer as an independent claim of authority.
93	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
94	pub enum Basis {
95	    IssuerMetadata,
96	    VerifiedCopyRecipe,
97	    UnverifiedMembership,
98	    OriginalObject,
99	}
100	#[derive(Clone, Debug, PartialEq, Eq)]
101	pub struct Loss {
102	    pub occurrence: Option<u64>,
103	    pub cid: Cid,
104	    pub expected_length: Option<u64>,
105	    pub state: Availability,
106	    pub basis: Basis,
107	}
108	/// Verified issuer metadata and sampled originals. Unavailable writer requests
109	/// remain unverified. This result is NOT an authenticated recovery history.
110	pub struct Member {
111	    context: Context,
112	    commitment: [u8; 32],
113	    frontier: Frontier,
114	    recipe_metadata_complete: bool,
115	    losses: Vec<Loss>,
116	    verified_requests: u64,
117	}
118	impl Member {
119	    pub fn context(&self) -> &Context {
120	        &self.context
121	    }
122	    pub fn commitment(&self) -> &[u8; 32] {
123	        &self.commitment
124	    }
125	    pub fn frontier(&self) -> &Frontier {
126	        &self.frontier
127	    }
128	    pub fn recipe_metadata_complete(&self) -> bool {
129	        self.recipe_metadata_complete
130	    }
131	    pub fn losses(&self) -> &[Loss] {
132	        &self.losses
133	    }
134	    pub fn verified_requests(&self) -> u64 {
135	        self.verified_requests
136	    }
137	}
138	struct Work {
139	    budget: Budget,
140	    deadline: Instant,
141	    bytes: u64,
142	}
143	impl Work {
144	    fn new(budget: Budget, items: usize) -> Result<Self> {
145	        require(
146	            !budget.duration.is_zero() && budget.duration <= Duration::from_secs(3600),
147	            "duration",
148	        )?;
149	        if u64::try_from(items).map_err(|_| Error::Budget)? > budget.items {
150	            return Err(Error::Budget);
151	        }
152	        let deadline = Instant::now()
153	            .checked_add(budget.duration)
154	            .ok_or(Error::Budget)?;
155	        let s = Self {
156	            budget,
157	            deadline,
158	            bytes: 0,
159	        };
160	        s.check()?;
161	        Ok(s)
162	    }
163	    fn check(&self) -> Result<()> {
164	        if self.budget.cancelled.load(Ordering::Relaxed) {
165	            return Err(Error::Cancelled);
166	        }
167	        if Instant::now() >= self.deadline {
168	            return Err(Error::Budget);
169	        }
170	        Ok(())
171	    }
172	    fn input(&mut self, size: usize) -> Result<()> {
173	        self.check()?;
174	        self.bytes = self.bytes.checked_add(size as u64).ok_or(Error::Budget)?;
175	        if self.bytes > self.budget.input_bytes {
176	            return Err(Error::Budget);
177	        }
178	        Ok(())
179	    }
180	    fn hash(&self, hash: &mut Sha256, bytes: &[u8]) -> Result<()> {
181	        for part in bytes.chunks(65536) {
182	            self.check()?;
183	            hash.update(part)
184	        }
185	        Ok(())
186	    }
187	    fn frame(&self, hash: &mut Sha256, bytes: &[u8]) -> Result<()> {
188	        hash.update((bytes.len() as u64).to_be_bytes());
189	        self.hash(hash, bytes)
190	    }
191	}
192	fn key(cid: &Cid) -> Result<String> {
193	    let b = cid.to_bytes();
194	    require(b.len() == 36 && b[..4] == [1, 0x55, 0x12, 0x20], "raw CID")?;
195	    Ok(cid.to_string())
196	}
197	fn ordered(last: &mut Option<String>, next: &str) -> Result<()> {
198	    require(
199	        last.as_ref().is_none_or(|x| x.as_str() < next),
200	        "CID order or duplicate",
201	    )?;
202	    *last = Some(next.into());
203	    Ok(())
204	}
205	fn known(bytes: &[u8], kind: Kind) -> Result<Record> {
206	    match evidence::decode(bytes).map_err(|_| Error::Invalid("metadata codec"))? {
207	        Decoded::Known(r) if r.kind() == kind => Ok(r),
208	        _ => Err(Error::Invalid("metadata profile")),
209	    }
210	}
211	struct Coordinate {
212	    cid: Cid,
213	    length: Option<u64>,
214	    referenced: bool,
215	    member: bool,
216	    original: Option<usize>,
217	    state: Availability,
218	}
219	fn length(c: &mut Coordinate, n: u64) -> Result<()> {
220	    require(
221	        (1..=MAX_OBJECT as u64).contains(&n),
222	        "forensic-recovery-required",
223	    )?;
224	    require(
225	        c.length.is_none_or(|old| old == n),
226	        "conflicting expected lengths",
227	    )?;
228	    c.length = Some(n);
229	    Ok(())
230	}
231	fn coordinate(cid: &Cid) -> Coordinate {
232	    Coordinate {
233	        cid: cid.clone(),
234	        length: None,
235	        referenced: false,
236	        member: false,
237	        original: None,
238	        state: Availability::Missing,
239	    }
240	}
241	fn did(s: &str) -> Result<()> {
242	    require(
243	        (56..=80).contains(&s.len()) && s.is_ascii() && s.starts_with("did:key:z"),
244	        "issuer encoding",
245	    )?;
246	    let (a, k) = atrium_crypto::did::parse_did_key(s).map_err(|_| Error::Invalid("issuer key"))?;
247	    require(
248	        a == atrium_crypto::Algorithm::P256
249	            && atrium_crypto::did::format_did_key(a, &k)
250	                .map_err(|_| Error::Invalid("issuer point"))?
251	                == s,
252	        "issuer key",
253	    )
254	}
255	
256	pub fn verify(input: Input<'_>, budget: Budget) -> Result<Member> {
257	    let ctx = input.context;
258	    require(matches!(ctx.profile, 2 | 3), "profile")?;
259	    did(&ctx.issuer)?;
260	    did(&ctx.observer)?;
261	    let count = input
262	        .records
263	        .len()
264	        .checked_add(input.membership.len())
265	        .and_then(|n| n.checked_add(input.objects.len()))
266	        .ok_or(Error::Budget)?;
267	    let mut work = Work::new(budget, count)?;
268	    let plan = match (ctx.profile, input.plan) {
269	        (2, None) => {
270	            require(input.membership.is_empty(), "profile2 membership")?;
271	            None
272	        }
273	        (3, Some(bytes)) => {
274	            work.input(bytes.len())?;
275	            let p = Plan::decode(bytes).map_err(|_| Error::Invalid("plan"))?;
276	            require(
277	                p.archive_id() == ctx.archive
278	                    && p.target().scope == ctx.scope
279	                    && p.target().issuer == ctx.issuer,
280	                "plan binding",
281	            )?;
282	            Some(p)
283	        }
284	        _ => return Err(Error::Invalid("profile plan")),
285	    };
286	    let mut keys = BTreeMap::<String, Coordinate>::new();
287	    let mut last = None;
288	    for m in input.membership {
289	        work.input(44)?;
290	        let k = key(m.cid)?;
291	        ordered(&mut last, &k)?;
292	        let mut c = coordinate(m.cid);
293	        length(&mut c, m.length)?;
294	        c.member = true;
295	        keys.insert(k, c);
296	    }
297	    let mut frontier = Frontier::default();
298	    let mut references = Vec::new();
299	    let mut writers = BTreeMap::<String, (u64, Cid)>::new();
300	    let mut operations = BTreeSet::new();
301	    let mut slots = BTreeMap::new();
302	    let mut source = Sha256::new();
303	    source.update(b"tools.kan.archive.copy-source.v1\0");
304	    work.frame(&mut source, b"commits")?;
305	    if let Some(p) = &plan {
306	        source.update(p.source().through.to_be_bytes())
307	    }
308	    for row in input.records {
309	        for (bytes, max) in [
310	            (row.manifest, 65536),
311	            (row.receipt, 65536),
312	            (row.proof, 16384),
313	        ] {
314	            require(!bytes.is_empty() && bytes.len() <= max, "metadata bounds")?;
315	            work.input(bytes.len())?;
316	        }
317	        require(row.sequence == frontier.through + 1, "record position")?;
318	        let m = known(row.manifest, Kind::Manifest)?;
319	        let r = known(row.receipt, Kind::Receipt)?;
320	        let p = proof::verify(
321	            row.proof,
322	            &proof::Context {
323	                issuer: &ctx.issuer,
324	                archive: ctx.archive,
325	                scope: ctx.scope,
326	            },
327	            &m,
328	            &r,
329	            &frontier,
330	        )
331	        .map_err(|_| Error::Invalid("issuer proof"))?;
332	        let retained = plan
333	            .as_ref()
334	            .is_some_and(|p| row.sequence <= p.source().through);
335	        require(
336	            p.purpose()
337	                == if retained {
338	                    Purpose::RetainedVerified
339	                } else {
340	                    Purpose::Admitted
341	                },
342	            "proof purpose",
343	        )?;
344	        if retained {
345	            let author = service::author(
346	                &plan
347	                    .as_ref()
348	                    .expect("retained plan")
349	                    .source()
350	                    .historical_issuer,
351	            )
352	            .map_err(|_| Error::Invalid("historical issuer"))?;
353	            require(r.body()["issuer"] == author, "historical receipt issuer")?;
354	        }
355	        let b = m.body();
356	        let wb = evidence::closed(
357	            &b["writer"],
358	            &["principal", "verificationMethod", "identityVersion"],
359	        )
360	        .map_err(|_| Error::Invalid("writer"))?;
361	        let writer =
362	            evidence::string(&wb["principal"], 80).map_err(|_| Error::Invalid("writer"))?;
363	        require(
364	            service::author(writer).map_err(|_| Error::Invalid("static writer"))? == b["writer"],
365	            "static writer",
366	        )?;
367	        let pos =
368	            evidence::uint(&b["position"]).map_err(|_| Error::Invalid("writer position"))? as u64;
369	        let expected = writers.get(writer);
370	        require(
371	            match expected {
372	                None => pos == 0 && b["previous"] == Ipld::Null,
373	                Some((old, cid)) => pos == old + 1 && b["previous"] == Ipld::Link(cid.clone()),
374	            },
375	            "writer predecessor",
376	        )?;
377	        let op = evidence::bytes(&b["operation"], 16).map_err(|_| Error::Invalid("operation"))?;
378	        require(
379	            operations.insert((writer.to_string(), op.to_vec())),
380	            "duplicate operation",
381	        )?;
382	        let Ipld::List(es) = &b["entries"] else {
383	            return Err(Error::Invalid("entries"));
384	        };
385	        require(es.len() == 1, "service request entry")?;
386	        let e = evidence::closed(&es[0], &["slot", "ciphertext", "length"])
387	            .map_err(|_| Error::Invalid("entry"))?;
388	        let cid =
389	            evidence::link(&e["ciphertext"], 0x55).map_err(|_| Error::Invalid("entry CID"))?;
390	        let n = evidence::uint(&e["length"]).map_err(|_| Error::Invalid("entry length"))? as u64;
391	        let k = key(cid)?;
392	        let c = keys.entry(k.clone()).or_insert_with(|| coordinate(cid));
393	        length(c, n)?;
394	        require(n <= service::MAX_REQUEST as u64, "service request length")?;
395	        require(!c.referenced, "reused service request CID")?;
396	        c.referenced = true;
397	        if retained {
398	            require(c.member, "retained reference absent from membership")?
399	        }
400	        let slot = evidence::bytes(&e["slot"], 32)
401	            .map_err(|_| Error::Invalid("slot"))?
402	            .to_vec();
403	        let expected_slot: [u8; 32] = Sha256::digest(op).into();
404	        require(slot.as_slice() == expected_slot, "service slot")?;
405	        let sk = (writer.to_string(), slot);
406	        let sv = (k.clone(), n);
407	        require(
408	            slots.get(&sk).is_none_or(|old| old == &sv),
409	            "conflicting slot binding",
410	        )?;
411	        slots.insert(sk, sv);
412	        if retained {
413	            source.update(row.sequence.to_be_bytes());
414	            work.frame(&mut source, row.manifest)?;
415	            work.frame(&mut source, row.receipt)?;
416	            work.frame(&mut source, &cid.to_bytes())?;
417	            let plan = plan.as_ref().expect("retained plan");
418	            if row.sequence == plan.source().through {
419	                require(plan.source().tip.as_ref() == Some(m.cid()), "source tip")?
420	            }
421	        }
422	        writers.insert(writer.to_string(), (pos, m.cid().clone()));
423	        references.push((row.sequence, k));
424	        frontier = p.frontier().clone();
425	        work.check()?;
426	    }
427	    let recipe_metadata_complete = if let Some(p) = &plan {
428	        work.frame(&mut source, b"objects")?;
429	        source.update((input.membership.len() as u64).to_be_bytes());
430	        for m in input.membership {
431	            work.check()?;
432	            work.frame(&mut source, &m.cid.to_bytes())?;
433	            source.update(m.length.to_be_bytes())
434	        }
435	        let digest: [u8; 32] = source.finalize().into();
436	        let full = frontier.through >= p.source().through;
437	        if full {
438	            require(digest == p.source().digest, "source metadata digest")?
439	        }
440	        full
441	    } else {
442	        true
443	    };
444	    if !recipe_metadata_complete {
445	        for c in keys.values_mut() {
446	            work.check()?;
447	            if !c.referenced {
448	                // Preserve the claimed length in M1, but do not let an
449	                // unauthenticated membership row classify or constrain bytes.
450	                c.length = None;
451	            }
452	        }
453	    }
454	    last = None;
455	    for (index, object) in input.objects.iter().enumerate() {
456	        require(
457	            object.bytes.len() <= MAX_OBJECT,
458	            "forensic-recovery-required",
459	        )?;
460	        work.input(object.bytes.len())?;
461	        let k = key(object.cid)?;
462	        ordered(&mut last, &k)?;
463	        let c = keys.entry(k).or_insert_with(|| coordinate(object.cid));
464	        if !recipe_metadata_complete {
465	            require(c.member, "untracked object in partial copy")?
466	        }
467	        c.original = Some(index);
468	        let mut hash = Sha256::new();
469	        work.hash(&mut hash, object.bytes)?;
470	        let actual: [u8; 32] = hash.finalize().into();
471	        let hash_valid = actual == object.cid.to_bytes()[4..];
472	        require(
473	            !hash_valid || c.length.is_none_or(|n| n == object.bytes.len() as u64),
474	            "hash-valid bytes contradict authenticated length",
475	        )?;
476	        let valid = !object.bytes.is_empty() && hash_valid;
477	        c.state = if valid {
478	            Availability::Available
479	        } else {
480	            Availability::Corrupt
481	        };
482	    }
483	    let mut losses = Vec::new();
484	    let mut verified_requests = 0;
485	    for ((sequence, k), row) in references.iter().zip(input.records) {
486	        work.check()?;
487	        let c = &keys[k];
488	        if c.state == Availability::Available {
489	            let committed = Committed {
490	                sequence: *sequence,
491	                manifest: known(row.manifest, Kind::Manifest)?,
492	                receipt: known(row.receipt, Kind::Receipt)?,
493	                duplicate: false,
494	            };
495	            service::verify_retained_request(
496	                &committed,
497	                input.objects[c.original.expect("available original")].bytes,
498	            )
499	            .map_err(|_| Error::Invalid("retained writer request"))?;
500	            verified_requests += 1;
501	        } else {
502	            losses.push(Loss {
503	                occurrence: Some(*sequence),
504	                cid: c.cid.clone(),
505	                expected_length: c.length,
506	                state: c.state,
507	                basis: Basis::IssuerMetadata,
508	            })
509	        }
510	    }
511	    for c in keys.values() {
512	        work.check()?;
513	        if !c.referenced && c.state != Availability::Available {
514	            losses.push(Loss {
515	                occurrence: None,
516	                cid: c.cid.clone(),
517	                expected_length: c.length,
518	                state: c.state,
519	                basis: if !c.member {
520	                    Basis::OriginalObject
521	                } else if recipe_metadata_complete {
522	                    Basis::VerifiedCopyRecipe
523	                } else {
524	                    Basis::UnverifiedMembership
525	                },
526	            })
527	        }
528	    }
529	    work.check()?;
530	    let framing_bytes = work
531	        .bytes
532	        .checked_mul(4)
533	        .and_then(|n| n.checked_add((count as u64).checked_mul(128)?))
534	        .and_then(|n| n.checked_add(1024))
535	        .ok_or(Error::Budget)?;
536	    let limits = Limits {
537	        items: count as u64,
538	        bytes: framing_bytes,
539	        duration: work.deadline.saturating_duration_since(Instant::now()),
540	        cancelled: work.budget.cancelled.clone(),
541	    };
542	    if limits.duration.is_zero() {
543	        return Err(Error::Budget);
544	    }
545	    let mut framing = MemberFraming::new(
546	        Header {
547	            profile: ctx.profile,
548	            archive: ctx.archive,
549	            scope: ctx.scope,
550	            issuer: &ctx.issuer,
551	            plan: input.plan,
552	        },
553	        Counts {
554	            membership: input.membership.len() as u64,
555	            records: input.records.len() as u64,
556	            objects: input.objects.len() as u64,
557	        },
558	        Domain::Member,
559	        limits,
560	    )
561	    .map_err(framing_error)?;
562	    for m in input.membership {
563	        framing.membership(m.cid, m.length).map_err(framing_error)?
564	    }
565	    framing.begin_records().map_err(framing_error)?;
566	    for r in input.records {
567	        framing
568	            .record(r.sequence, r.manifest, r.receipt, r.proof)
569	            .map_err(framing_error)?
570	    }
571	    framing.begin_objects().map_err(framing_error)?;
572	    for o in input.objects {
573	        framing
574	            .original_object(o.cid, o.bytes)
575	            .map_err(framing_error)?
576	    }
577	    let commitment = framing.finish().map_err(framing_error)?;
578	    work.check()?;
579	    Ok(Member {
580	        context: ctx.clone(),
581	        commitment,
582	        frontier,
583	        recipe_metadata_complete,
584	        losses,
585	        verified_requests,
586	    })
587	}
588

